-- Generated by `supabase@3.0.0 migration new target_reward_probability_two_seven_twenty`.
-- New normal correct answers use 2% / 7% / 20% / 71%. Stored awards, balances,
-- bonus windows, replay receipts and the helper's existing private ACL stay intact.
CREATE OR REPLACE FUNCTION target_private.reward_points_for_roll(p_roll integer)
RETURNS integer LANGUAGE sql IMMUTABLE STRICT SECURITY INVOKER SET search_path=pg_catalog AS $$
  SELECT CASE WHEN p_roll BETWEEN 0 AND 1 THEN 100000 WHEN p_roll BETWEEN 2 AND 8 THEN 10000
    WHEN p_roll BETWEEN 9 AND 28 THEN 1000 WHEN p_roll BETWEEN 29 AND 99 THEN 100 ELSE NULL END;
$$;
